//! Explicit disclosure projections. Adding a database column cannot silently
//! add a password, capability verifier or transport credential to an export.
pub(super) struct Section {
    pub name: &'static str,
    pub query: &'static str,
}

// Identity dependencies include retained memberships and completed/prepared
// identity requests plus explicit support actors. UUID casts fail closed on
// unsupported persisted data rather than silently omitting a dependency.
pub(super) const OWNERS: &str = "WITH owners AS (SELECT end_user_id AS id FROM aegaeon.organization_memberships WHERE environment_id=$1 AND domain_id=$2 UNION SELECT target_user_id FROM aegaeon.organization_identity_requests WHERE environment_id=$1 AND domain_id=$2 AND target_user_id IS NOT NULL UNION SELECT (result->>'userId')::uuid FROM aegaeon.organization_identity_requests WHERE environment_id=$1 AND domain_id=$2 AND result IS NOT NULL UNION SELECT (recipient_binding->'binding'->>'user_id')::uuid FROM aegaeon.organization_invitation_challenges WHERE environment_id=$1 AND domain_id=$2 UNION SELECT user_id FROM aegaeon.organization_admin_access_grants WHERE environment_id=$1 AND domain_id=$2)";

pub(super) const SECTIONS: &[Section] = &[
    Section { name: "domain", query: "SELECT (id)::text AS row_key,to_jsonb(v)::text AS row_data FROM (SELECT id,environment_id,name,is_default,enabled,revision,invitation_delivery,support_policy,support_policy_revision FROM aegaeon.authorization_domains WHERE environment_id=$1 AND id=$2) v" },
    Section { name: "targets", query: "SELECT (audience)::text AS row_key,to_jsonb(v)::text AS row_data FROM (SELECT environment_id,domain_id,audience,management,introspection_clients FROM aegaeon.authorization_domain_targets WHERE environment_id=$1 AND domain_id=$2) v" },
    Section { name: "roles", query: "SELECT (role_key)::text AS row_key,to_jsonb(v)::text AS row_data FROM (SELECT environment_id,domain_id,role_key,version,privileges,manages_members,assignable_roles FROM aegaeon.organization_role_definitions WHERE environment_id=$1 AND domain_id=$2) v" },
    Section { name: "client_bindings", query: "SELECT (id)::text AS row_key,to_jsonb(v)::text AS row_data FROM (SELECT id,environment_id,domain_id,client_registration_id,client_identifier,active,revision,targets,created_at FROM aegaeon.organization_client_bindings WHERE environment_id=$1 AND domain_id=$2) v" },
    Section { name: "operators", query: "SELECT (id)::text AS row_key,to_jsonb(v)::text AS row_data FROM (SELECT id,environment_id,domain_id,administrator_id,active,revision,capabilities,created_at FROM aegaeon.organization_operator_grants WHERE environment_id=$1 AND domain_id=$2) v" },
    Section { name: "organizations", query: "SELECT (id)::text AS row_key,to_jsonb(v)::text AS row_data FROM (SELECT id,environment_id,domain_id,external_id,state,revision,grant_generation,created_at FROM aegaeon.application_organizations WHERE environment_id=$1 AND domain_id=$2) v" },
    Section { name: "memberships", query: "SELECT (jsonb_build_array(organization_id,end_user_id)::text)::text AS row_key,to_jsonb(v)::text AS row_data FROM (SELECT environment_id,domain_id,organization_id,end_user_id,incarnation,state,revision,grant_generation,roles FROM aegaeon.organization_memberships WHERE environment_id=$1 AND domain_id=$2) v" },
    Section { name: "invitations", query: "SELECT (id)::text AS row_key,to_jsonb(v)::text AS row_data FROM (SELECT id,environment_id,domain_id,organization_id,revision,state,recipient,authority,issued_at,expires_at,delivery_revision,delivered_at,accepted_challenge_id,result,delivery_outcome FROM aegaeon.organization_invitations WHERE environment_id=$1 AND domain_id=$2) v" },
    Section { name: "challenges", query: "SELECT (id)::text AS row_key,to_jsonb(v)::text AS row_data FROM (SELECT id,environment_id,domain_id,invitation_id,invitation_delivery_revision,recipient_binding,request_key,issued_at,expires_at,delivery_revision,delivered_at,delivery_outcome FROM aegaeon.organization_invitation_challenges WHERE environment_id=$1 AND domain_id=$2) v" },
    Section { name: "identity_requests", query: "SELECT (id)::text AS row_key,to_jsonb(v)::text AS row_data FROM (SELECT id,environment_id,domain_id,invitation_id,invitation_delivery_revision,policy_revision,purpose,request_key,encode(request_digest,'hex') AS request_digest,target_user_id,target_identity_revision,issued_at,expires_at,state,result,delivery_revision,delivered_at,delivery_outcome FROM aegaeon.organization_identity_requests WHERE environment_id=$1 AND domain_id=$2) v" },
    Section { name: "administrative_grants", query: "SELECT (id)::text AS row_key,to_jsonb(v)::text AS row_data FROM (SELECT id,environment_id,domain_id,organization_id,user_id,client_registration_id,root_id,authority,revision,active,issued_at,expires_at,creation_key,encode(request_digest,'hex') AS request_digest,revocation_key,encode(revocation_digest,'hex') AS revocation_digest FROM aegaeon.organization_admin_access_grants WHERE environment_id=$1 AND domain_id=$2) v" },
    Section { name: "audit", query: "SELECT (id)::text AS row_key,to_jsonb(v)::text AS row_data FROM (SELECT id,environment_id,domain_id,organization_id,actor_id,actor_kind,client_id,client_registration_id,request_id,reason,event_type,data,created_at FROM aegaeon.organization_authority_events WHERE environment_id=$1 AND domain_id=$2) v" },
    Section { name: "receipts", query: "SELECT (jsonb_build_array(actor_id,actor_kind,client_id,client_registration_id,operation,idempotency_key)::text)::text AS row_key,to_jsonb(v)::text AS row_data FROM (SELECT environment_id,domain_id,actor_id,actor_kind,client_id,client_registration_id,operation,idempotency_key,encode(request_digest,'hex') AS request_digest,result,created_at FROM aegaeon.organization_authority_receipts WHERE environment_id=$1 AND domain_id=$2) v" },
    Section { name: "outbox", query: "SELECT (event_id)::text AS row_key,to_jsonb(v)::text AS row_data FROM (SELECT event_id,attempts,delivered_at FROM aegaeon.organization_authority_outbox WHERE EXISTS(SELECT 1 FROM aegaeon.organization_authority_events e WHERE e.id=event_id AND e.environment_id=$1 AND e.domain_id=$2)) v" },
    Section { name: "owners", query: "SELECT row_key,row_data FROM aegaeon.organization_snapshot_history_v1($1,$2,'owners',$3,$5::bigint::integer)" },
    Section { name: "subject_history", query: "SELECT row_key,row_data FROM aegaeon.organization_snapshot_history_v1($1,$2,'subject_history',$3,$5::bigint::integer)" },
    Section { name: "identities", query: "SELECT (id)::text AS row_key,to_jsonb(v)::text AS row_data FROM (SELECT id,environment_id,subject,status,created_at,updated_at,organization_identity_revision,organization_reauthentication_after FROM aegaeon.end_users WHERE environment_id=$1 AND id IN (SELECT id FROM owners)) v" },
    Section { name: "namespace", query: "SELECT (environment_id)::text AS row_key,to_jsonb(v)::text AS row_data FROM (SELECT environment_id,issuer_host,origin,contract_version,recorded_at FROM aegaeon.subject_ownership_namespaces WHERE environment_id=$1 AND EXISTS(SELECT 1 FROM aegaeon.authorization_domains WHERE environment_id=$1 AND id=$2)) v" },
    Section { name: "environment_dependency", query: "SELECT (id)::text AS row_key,to_jsonb(v)::text AS row_data FROM (SELECT id,issuer_host,issuer_url,status,active_configuration_version_id,organization_identity_policy,organization_identity_policy_revision FROM aegaeon.environments WHERE id=$1 AND EXISTS(SELECT 1 FROM aegaeon.authorization_domains WHERE environment_id=$1 AND id=$2)) v" },
    Section { name: "client_dependencies", query: "SELECT (id)::text AS row_key,to_jsonb(v)::text AS row_data FROM (SELECT id,environment_id,configuration_version_id,client_identifier,client_type,status,deleted_at,allowed_grant_types,allowed_scopes,dpop_bound_access_tokens,token_endpoint_authentication_method FROM aegaeon.clients WHERE environment_id=$1 AND id IN (SELECT client_registration_id FROM aegaeon.organization_client_bindings WHERE environment_id=$1 AND domain_id=$2)) v" },
];
